-- Generated by npm run sql:generate.
-- For installations that already applied migration 007 (categories).
-- Run in Supabase SQL Editor as postgres. No images or questions are deleted.
begin;
do $$ begin
  if to_regclass('public.game_categories') is null then
    raise exception 'Apply upgrade_existing.sql first to install game categories.';
  end if;
end $$;
-- Game-wide instructions; image questions keep reusable answers independently.
set constraints all immediate;
set constraints all deferred;
alter table public.games add column if not exists prompt_key text not null default 'what_is_this'
  check (prompt_key in ('what_is_this','guess_animal','name_food','name_object','name_vehicle'));

-- Repair legacy draft games that still owned a published private session.
update public.levels l set is_published = g.is_published
from public.games g where l.game_id = g.id and l.is_published is distinct from g.is_published;

create or replace function public.create_standalone_game(content jsonb)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare created public.games%rowtype; begin
  insert into public.games (name, slug, description, difficulty, category_id, prompt_key, is_published)
  values (content->>'name', content->>'slug', content->>'description', (content->>'difficulty')::smallint,
    coalesce((content->>'category_id')::uuid, (select id from public.game_categories where slug = 'guess')),
    coalesce(content->>'prompt_key', 'what_is_this'), false)
  returning * into created;
  insert into public.levels (game_id, name, question_count, default_time_limit_seconds)
  values (created.id, created.name, coalesce((content->>'question_count')::integer, 5), coalesce((content->>'default_time_limit_seconds')::integer, 5));
  return to_jsonb(created);
end $$;
create or replace function public.update_standalone_game(target_game_id uuid, changes jsonb)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare saved public.games%rowtype; begin
  perform pg_catalog.pg_advisory_xact_lock(74821, 1);
  update public.games set
    name = case when changes ? 'name' then changes->>'name' else name end,
    slug = case when changes ? 'slug' then changes->>'slug' else slug end,
    description = case when changes ? 'description' then changes->>'description' else description end,
    difficulty = case when changes ? 'difficulty' then (changes->>'difficulty')::smallint else difficulty end,
    category_id = case when changes ? 'category_id' then (changes->>'category_id')::uuid else category_id end,
    prompt_key = case when changes ? 'prompt_key' then changes->>'prompt_key' else prompt_key end,
    is_published = case when changes ? 'is_published' then (changes->>'is_published')::boolean else is_published end
  where id = target_game_id returning * into saved;
  if not found then raise exception 'Game not found' using errcode = 'P0002'; end if;
  update public.levels set name = saved.name, is_published = saved.is_published,
    question_count = case when changes ? 'question_count' then (changes->>'question_count')::integer else question_count end,
    default_time_limit_seconds = case when changes ? 'default_time_limit_seconds' then (changes->>'default_time_limit_seconds')::integer else default_time_limit_seconds end
  where game_id = target_game_id;
  return to_jsonb(saved);
end $$;
create or replace function public.set_game_questions(target_game_id uuid, question_ids uuid[])
returns void language plpgsql security invoker set search_path = '' as $$
declare session_id uuid; previous_ids uuid[]; begin
  perform pg_catalog.pg_advisory_xact_lock(74821, 1);
  if cardinality(coalesce(question_ids, '{}'::uuid[])) > 100 then
    raise exception 'A game can contain at most 100 questions' using errcode = 'YP001';
  end if;
  select id into session_id from public.levels where game_id = target_game_id for update;
  if not found then raise exception 'Game not found' using errcode = 'P0002'; end if;
  select coalesce(array_agg(question_id order by order_index), '{}'::uuid[]) into previous_ids
  from public.level_questions where level_id = session_id;
  -- Re-saving an unchanged published list must not unpublish it.
  if previous_ids = coalesce(question_ids, '{}'::uuid[]) then return; end if;
  update public.games set is_published = false where id = target_game_id;
  update public.levels set is_published = false, question_count = greatest(1, cardinality(coalesce(question_ids, '{}'::uuid[]))) where id = session_id;
  perform public.set_level_questions(session_id, question_ids);
end $$;
revoke all on function public.create_standalone_game(jsonb), public.update_standalone_game(uuid,jsonb), public.set_game_questions(uuid,uuid[]) from public, anon, authenticated;
grant execute on function public.create_standalone_game(jsonb), public.update_standalone_game(uuid,jsonb), public.set_game_questions(uuid,uuid[]) to service_role;

create or replace function public.assert_published_content()
returns void language plpgsql security definer set search_path = '' as $$
declare invalid_level public.levels%rowtype;
begin
  select l.* into invalid_level from public.levels l where l.is_published and (
    (select count(*) from public.level_questions lq where lq.level_id = l.id) <> l.question_count
    or exists (
      select 1 from public.level_questions lq
      join public.questions q on q.id = lq.question_id
      where lq.level_id = l.id and (
        not q.is_active or btrim(q.primary_answer) = '' or btrim(q.language) = ''
        or not exists (select 1 from public.media_records m where m.storage_path = q.image_storage_path and m.status = 'ready')
        or not exists (select 1 from public.question_answers a where a.question_id = q.id and a.is_primary and a.answer = q.primary_answer)
      )
    )
  ) limit 1;
  if found then
    raise exception 'Game "%" needs exactly % active questions, uploaded images and primary answers. Save the game as a draft before changing its content.',
      invalid_level.name, invalid_level.question_count using errcode = 'YP001';
  end if;
  if exists (select 1 from public.games g where g.is_published and not exists (
    select 1 from public.levels l where l.game_id = g.id and l.is_published
  )) then
    raise exception 'A published game needs a complete saved question selection. Save game questions before publishing.' using errcode = 'YP001';
  end if;
end $$;
revoke all on function public.assert_published_content() from public, anon, authenticated;
grant execute on function public.assert_published_content() to service_role;
commit;
